n      // Do nothing\\n    } @else if not comparable($prev-num, $num) {\\n      @warn \\"Potentially invalid value for #{$map-name}: This map must be in ascending order, but key \'#{$key}\' has value #{$num} whose unit makes it incomparable to #{$prev-num}, the value of the previous key \'#{$prev-key}\' !\\";\\n    } @else if $prev-num >= $num {\\n      @warn \\"Invalid value for #{$map-name}: This map must be in ascending order, but key \'#{$key}\' has value #{$num} which isn\'t greater than #{$prev-num}, the value of the previous key \'#{$prev-key}\' !\\";\\n    }\\n    $prev-key: $key;\\n    $prev-num: $num;\\n  }\\n}\\n\\n// Starts at zero\\n// Used to ensure the min-width of the lowest breakpoint starts at 0.\\n@mixin _assert-starts-at-zero($map, $map-name: \\"$grid-breakpoints\\") {\\n  @if length($map) > 0 {\\n    $values: map-values($map);\\n    $first-value: nth($values, 1);\\n    @if $first-value != 0 {\\n      @warn \\"First breakpoint in #{$map-name} must start at 0, but starts at #{$first-value}.\\";\\n    }\\n  }\\n}\\n\\n// Replace `$search` with `$replace` in `$string`\\n// Used on our SVG icon backgrounds for custom forms.\\n//\\n// @author Hugo Giraudel\\n// @param {String} $string - Initial string\\n// @param {String} $search - Substring to replace\\n// @param {String} $replace (\'\') - New value\\n// @return {String} - Updated string\\n@function str-replace($string, $search, $replace: \\"\\") {\\n  $index: str-index($string, $search);\\n\\n  @if $index {\\n    @return str-slice($string, 1, $index - 1) + $replace + str-replace(str-slice($string, $index + str-length($search)), $search, $replace);\\n  }\\n\\n  @return $string;\\n}\\n\\n// See https://codepen.io/kevinweber/pen/dXWoRw\\n//\\n// Requires the use of quotes around data URIs.\\n\\n@function escape-svg($string) {\\n  @if str-index($string, \\"data:image/svg+xml\\") {\\n    @each $char, $encoded in $escaped-characters {\\n      // Do not escape the url brackets\\n      @if str-index($string, \\"url(\\") == 1 {\\n        $string: url(\\"#{str-replace(str-slice($string, 6, -3), $char, $encoded)}\\");\\n      } @else {\\n        $string: str-replace($string, $char, $encoded);\\n      }\\n    }\\n  }\\n\\n  @return $string;\\n}\\n\\n// Color contrast\\n@function color-yiq($color, $dark: $yiq-text-dark, $light: $yiq-text-light) {\\n  $r: red($color);\\n  $g: green($color);\\n  $b: blue($color);\\n\\n  $yiq: (($r * 299) + ($g * 587) + ($b * 114)) * .001;\\n\\n  @if ($yiq >= $yiq-contrasted-threshold) {\\n    @return $dark;\\n  } @else {\\n    @return $light;\\n  }\\n}\\n\\n// Retrieve color Sass maps\\n@function color($key: \\"blue\\") {\\n  @return map-get($colors, $key);\\n}\\n\\n@function theme-color($key: \\"primary\\") {\\n  @return map-get($theme-colors, $key);\\n}\\n\\n@function gray($key: \\"100\\") {\\n  @return map-get($grays, $key);\\n}\\n\\n// Request a theme color level\\n@function theme-color-level($color-name: \\"primary\\", $level: 0) {\\n  $color: theme-color($color-name);\\n  $color-base: if($level > 0, $black, $white);\\n  $level: abs($level);\\n\\n  @return mix($color-base, $color, $level * $theme-color-interval);\\n}\\n\\n// Return valid calc\\n@function add($value1, $value2, $return-calc: true) {\\n  @if $value1 == null {\\n    @return $value2;\\n  }\\n\\n  @if $value2 == null {\\n    @return $value1;\\n  }\\n\\n  @if type-of($value1) == number and type-of($value2) == number and comparable($value1, $value2) {\\n    @return $value1 + $value2;\\n  }\\n\\n  @return if($return-calc == true, calc(#{$value1} + #{$value2}), $value1 + unquote(\\" + \\") + $value2);\\n}\\n\\n@function subtract($value1, $value2, $return-calc: true) {\\n  @if $value1 == null and $value2 == null {\\n    @return null;\\n  }\\n\\n  @if $value1 == null {\\n    @return -$value2;\\n  }\\n\\n  @if $value2 == null {\\n    @return $value1;\\n  }\\n\\n  @if type-of($value1) == number and type-of($value2) == number and comparable($value1, $value2) {\\n    @return $value1 - $value2;\\n  }\\n\\n  @if type-of($value2) != number {\\n    $value2: unquote(\\"(\\") + $value2 + unquote(\\")\\");\\n  }\\n\\n  @return if($return-calc == true, calc(#{$value1} - #{$value2}), $value1 + unquote(\\" - \\") + $value2);\\n}\\n\\n@function divide($dividend, $divisor, $precision: 10) {\\n  $sign: if($dividend > 0 and $divisor > 0 or $dividend < 0 and $divisor < 0, 1, -1);\\n  $dividend: abs($dividend);\\n  $divisor: abs($divisor);\\n  @if $dividend == 0 {\\n    @return 0;\\n  }\\n  @if $divisor == 0 {\\n    @error \\"Cannot divide by 0\\";\\n  }\\n  $remainder: $dividend;\\n  $result: 0;\\n  $factor: 10;\\n  @while ($remainder > 0 and $precision >= 0) {\\n    $quotient: 0;\\n    @while ($remainder >= $divisor) {\\n      $remainder: $remainder - $divisor;\\n      $quotient: $quotient + 1;\\n    }\\n    $result: $result * 10 + $quotient;\\n    $factor: $factor * .1;\\n    $remainder: $remainder * 10;\\n    $precision: $precision - 1;\\n    @if ($precision < 0 and $remainder >= $divisor * 5) {\\n      $result: $result + 1;\\n    }\\n  }\\n  $result: $result * $factor * $sign;\\n  $dividend-unit: unit($dividend);\\n  $divisor-unit: unit($divisor);\\n  $unit-map: (\\n    \\"px\\": 1px,\\n    \\"rem\\": 1rem,\\n    \\"em\\": 1em,\\n    \\"%\\": 1%\\n  );\\n  @if ($dividend-unit != $divisor-unit and map-has-key($unit-map, $dividend-unit)) {\\n    $result: $result * map-get($unit-map, $dividend-unit);\\n  }\\n  @return $result;\\n}\\n","// stylelint-disable selector-no-qualifying-type\\n\\n//\\n// Textual form controls\\n//\\n\\n.form-control {\\n  display: block;\\n  width: 100%;\\n  height: $input-height;\\n  padding: $input-padding-y $input-padding-x;\\n  font-family: $input-font-family;\\n  @include font-size($input-font-size);\\n  font-weight: $input-font-weight;\\n  line-height: $input-line-height;\\n  color: $input-color;\\n  background-color: $input-bg;\\n  background-clip: padding-box;\\n  border: $input-border-width solid $input-border-color;\\n\\n  // Note: This has no effect on <select>s in some browsers, due to the limited stylability of `<select>`s in CSS.\\n  @include border-radius($input-border-radius, 0);\\n\\n  @include box-shadow($input-box-shadow);\\n  @include transition($input-transition);\\n\\n  // Unstyle the caret on `<select>`s in IE10+.\\n  &::-ms-expand {\\n    background-color: transparent;\\n    border: 0;\\n  }\\n\\n  // Customize the `:focus` state to imitate native WebKit styles.\\n  @include form-control-focus($ignore-warning: true);\\n\\n  // Placeholder\\n  &::placeholder {\\n    color: $input-placeholder-color;\\n    // Override Firefox\'s unusual default opacity; see https://github.com/twbs/bootstrap/pull/11526.\\n    opacity: 1;\\n  }\\n\\n  // Disabled and read-only inputs\\n  //\\n  // HTML5 says that controls under a fieldset > legend:first-child won\'t be\\n  // disabled if the fieldset is disabled. Due to implementation difficulty, we\\n  // don\'t honor that edge case; we style them as disabled anyway.\\n  &:disabled,\\n  &[readonly] {\\n    background-color: $input-disabled-bg;\\n    // iOS fix for unreadable disabled content; see https://github.com/twbs/bootstrap/issues/11655.\\n    opacity: 1;\\n  }\\n}\\n\\ninput[type=\\"date\\"],\\ninput[type=\\"time\\"],\\ninput[type=\\"datetime-local\\"],\\ninput[type=\\"month\\"] {\\n  &.form-control {\\n    appearance: none; // Fix appearance for date inputs in Safari\\n  }\\n}\\n\\nselect.form-control {\\n  // Remove select outline from select box in FF\\n  &:-moz-focusring {\\n    color: transparent;\\n    text-shadow: 0 0 0 $input-color;\\n  }\\n\\n  &:focus::-ms-value {\\n    // Suppress the nested default white text on blue background highlight given to\\n    // the selected option text when the (still closed) <select> receives focus\\n    // in IE and (under certain conditions) Edge, as it looks bad and cannot be made to\\n    // match the appearance of the native widget.\\n    // See https://github.com/twbs/bootstrap/issues/19398.\\n    color: $input-color;\\n    background-color: $input-bg;\\n  }\\n}\\n\\n// Make file inputs better match text inputs by forcing them to new lines.\\n.form-control-file,\\n.form-control-range {\\n  display: block;\\n  width: 100%;\\n}\\n\\n\\n//\\n// Labels\\n//\\n\\n// For use with horizontal and inline forms, when you need the label (or legend)\\n// text to align with the form controls.\\n.col-form-label {\\n  padding-top: add($input-padding-y, $input-border-width);\\n  padding-bottom: add($input-padding-y, $input-border-width);\\n  margin-bottom: 0; // Override the `<label>/<legend>` default\\n  @include font-size(inherit); // Override the `<legend>` default\\n  line-height: $input-line-height;\\n}\\n\\n.col-form-label-lg {\\n  padding-top: add($input-padding-y-lg, $input-border-width);\\n  padding-bottom: add($input-padding-y-lg, $input-border-width);\\n  @include font-size($input-font-size-lg);\\n  line-height: $input-line-height-lg;\\n}\\n\\n.col-form-label-sm {\\n  padding-top: add($input-padding-y-sm, $input-border-width);\\n  padding-bottom: add($input-padding-y-sm, $input-border-width);\\n  @include font-size($input-font-size-sm);\\n  line-height: $input-line-height-sm;\\n}\\n\\n\\n// Readonly controls as plain text\\n//\\n// Apply class to a readonly input to make it appear like regular plain\\n// text (without any border, background color, focus indicator)\\n\\n.form-control-plaintext {\\n  display: block;\\n  width: 100%;\\n  padding: $input-padding-y 0;\\n  margin-bottom: 0; // match inputs if this class comes on inputs with default margins\\n  @include font-size($input-font-size);\\n  line-height: $input-line-height;\\n  color: $input-plaintext-color;\\n  background-color: transparent;\\n  border: solid transparent;\\n  border-width: $input-border-width 0;\\n\\n  &.form-control-sm,\\n  &.form-control-lg {\\n    padding-right: 0;\\n    padding-left: 0;\\n  }\\n}\\n\\n\\n// Form control sizing\\n//\\n// Build on `.form-control` with modifier classes to decrease or increase the\\n// height and font-size of form controls.\\n//\\n// Repeated in `_input_group.scss` to avoid Sass extend issues.\\n\\n.form-control-sm {\\n  height: $input-height-sm;\\n  padding: $input-padding-y-sm $input-padding-x-sm;\\n  @include font-size($input-font-size-sm);\\n  line-height: $input-line-height-sm;\\n  @include border-radius($input-border-radius-sm);\\n}\\n\\n.form-control-lg {\\n  height: $input-height-lg;\\n  padding: $input-padding-y-lg $input-padding-x-lg;\\n  @include font-size($input-font-size-lg);\\n  line-height: $input-line-height-lg;\\n  @include border-radius($input-border-radius-lg);\\n}\\n\\n// stylelint-disable-next-line no-duplicate-selectors\\nselect.form-control {\\n  &[size],\\n  &[multiple] {\\n    height: auto;\\n  }\\n}\\n\\ntextarea.form-control {\\n  height: auto;\\n}\\n\\n// Form groups\\n//\\n// Designed to help with the organization and spacing of vertical forms. For\\n// horizontal forms, use the predefined grid classes.\\n\\n.form-group {\\n  margin-bottom: $form-group-margin-bottom;\\n}\\n\\n.form-text {\\n  display: block;\\n  margin-top: $form-text-margin-top;\\n}\\n\\n\\n// Form grid\\n//\\n// Special replacement for our grid system\'s `.row` for tighter form layouts.\\n\\n.form-row {\\n  display: flex;\\n  flex-wrap: wrap;\\n  margin-right: -$form-grid-gutter-width * .5;\\n  margin-left: -$form-grid-gutter-width * .5;\\n\\n  > .col,\\n  > [class*=\\"col-\\"] {\\n    padding-right: $form-grid-gutter-width * .5;\\n    padding-left: $form-grid-gutter-width * .5;\\n  }\\n}\\n\\n\\n// Checkboxes and radios\\n//\\n// Indent the labels to position radios/checkboxes as hanging controls.\\n\\n.form-check {\\n  position: relative;\\n  display: block;\\n  padding-left: $form-check-input-gutter;\\n}\\n\\n.form-check-input {\\n  position: absolute;\\n  margin-top: $form-check-input-margin-y;\\n  margin-left: -$form-check-input-gutter;\\n\\n  // Use [disabled] and :disabled for workaround https://github.com/twbs/bootstrap/issues/28247\\n  &[disabled] ~ .form-check-label,\\n  &:disabled ~ .form-check-label {\\n    color: $text-muted;\\n  }\\n}\\n\\n.form-check-label {\\n  margin-bottom: 0; // Override default `<label>` bottom margin\\n}\\n\\n.form-check-inline {\\n  display: inline-flex;\\n  align-items: center;\\n  padding-left: 0; // Override base .form-check\\n  margin-right: $form-check-inline-margin-x;\\n\\n  // Undo .form-check-input defaults and add some `margin-right`.\\n  .form-check-input {\\n    position: static;\\n    margin-top: 0;\\n    margin-right: $form-check-inline-input-margin-x;\\n    margin-left: 0;\\n  }\\n}\\n\\n\\n// Form validation\\n//\\n// Provide feedback to users when form field values are valid or invalid. Works\\n// primarily for client-side validation via scoped `:invalid` and `:valid`\\n// pseudo-classes but also includes `.is-invalid` and `.is-valid` classes for\\n// server side validation.\\n\\n@each $state, $data in $form-validation-states {\\n  @include form-validation-state($state, map-get($data, color), map-get($data, icon));\\n}\\n\\n// Inline forms\\n//\\n// Make forms appear inline(-block) by adding the `.form-inline` class. Inline\\n// forms begin stacked on extra small (mobile) devices and then go inline when\\n// viewports reach <768px.\\n//\\n// Requires wrapping inputs and labels with `.form-group` for proper display of\\n// default HTML form controls and our custom form controls (e.g., input groups).\\n\\n.form-inline {\\n  display: flex;\\n  flex-flow: row wrap;\\n  align-items: center; // Prevent shorter elements from growing to same height as others (e.g., small buttons growing to normal sized button height)\\n\\n  // Because we use flex, the initial sizing of checkboxes is collapsed and\\n  // doesn\'t occupy the full-width (which is what we want for xs grid tier),\\n  // so we force that here.\\n  .form-check {\\n    width: 100%;\\n  }\\n\\n  // Kick in the inline\\n  @include media-breakpoint-up(sm) {\\n    label {\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      margin-bottom: 0;\\n    }\\n\\n    // Inline-block all the things for \\"inline\\"\\n    .form-group {\\n      display: flex;\\n      flex: 0 0 auto;\\n      flex-flow: row wrap;\\n      align-items: center;\\n      margin-bottom: 0;\\n    }\\n\\n    // Allow folks to *not* use `.form-group`\\n    .form-control {\\n      display: inline-block;\\n      width: auto; // Prevent labels from stacking above inputs in `.form-group`\\n      vertical-align: middle;\\n    }\\n\\n    // Make static controls behave like regular ones\\n    .form-control-plaintext {\\n      display: inline-block;\\n    }\\n\\n    .input-group,\\n    .custom-select {\\n      width: auto;\\n    }\\n\\n    // Remove default margin on radios/checkboxes that were used for stacking, and\\n    // then undo the floating of radios and checkboxes to match.\\n    .form-check {\\n      display: flex;\\n      align-items: center;\\n      justify-content: center;\\n      width: auto;\\n      padding-left: 0;\\n    }\\n    .form-check-input {\\n      position: relative;\\n      flex-shrink: 0;\\n      margin-top: 0;\\n      margin-right: $form-check-input-margin-x;\\n      margin-left: 0;\\n    }\\n\\n    .custom-control {\\n      align-items: center;\\n      justify-content: center;\\n    }\\n    .custom-control-label {\\n      margin-bottom: 0;\\n    }\\n  }\\n}\\n","// stylelint-disable property-disallowed-list\\n@mixin transition($transition...) {\\n  @if length($transition) == 0 {\\n    $transition: $transition-base;\\n  }\\n\\n  @if length($transition) > 1 {\\n    @each $value in $transition {\\n      @if $value == null or $value == none {\\n        @warn \\"The keyword \'none\' or \'null\' must be used as a single argument.\\";\\n      }\\n    }\\n  }\\n\\n  @if $enable-transitions {\\n    @if nth($transition, 1) != null {\\n      transition: $transition;\\n    }\\n\\n    @if $enable-prefers-reduced-motion-media-query and nth($transition, 1) != null and nth($transition, 1) != none {\\n      @media (prefers-reduced-motion: reduce) {\\n        transition: none;\\n      }\\n    }\\n  }\\n}\\n","// Form control focus state\\n//\\n// Generate a customized focus state and for any input with the specified color,\\n// which defaults to the `$input-focus-border-color` variable.\\n//\\n// We highly encourage you to not customize the default value, but instead use\\n// this to tweak colors on an as-needed basis. This aesthetic change is based on\\n// WebKit\'s default styles, but applicable to a wider range of browsers. Its\\n// usability and accessibility should be taken into account with any change.\\n//\\n// Example usage: change the default blue border and shadow to white for better\\n// contrast against a dark gray background.\\n@mixin form-control-focus($ignore-warning: false) {\\n  &:focus {\\n    color: $input-focus-color;\\n    background-color: $input-focus-bg;\\n    border-color: $input-focus-border-color;\\n    outline: 0;\\n    @if $enable-shadows {\\n      @include box-shadow($input-box-shadow, $input-focus-box-shadow);\\n    } @else {\\n      // Avoid using mixin so we can pass custom focus shadow properly\\n      box-shadow: $input-focus-box-shadow;\\n    }\\n  }\\n  @include deprecate(\\"The `form-control-focus()` mixin\\", \\"v4.4.0\\", \\"v5\\", $ignore-warning);\\n}\\n\\n// This mixin uses an `if()` technique to be compatible with Dart Sass\\n// See https://github.com/sass/sass/issues/1873#issuecomment-152293725 for more details\\n@mixin form-validation-state-selector($state) {\\n  @if ($state == \\"valid\\" or $state == \\"invalid\\") {\\n    .was-validated #{if(&, \\"&\\", \\"\\")}:#{$state},\\n    #{if(&, \\"&\\", \\"\\")}.is-#{$state} {\\n      @content;\\n    }\\n  } @else {\\n    #{if(&, \\"&\\", \\"\\")}.is-#{$state} {\\n      @content;\\n    }\\n  }\\n}\\n\\n@mixin form-validation-state($state, $color, $icon) {\\n  .#{$state}-feedback {\\n    display: none;\\n    width: 100%;\\n    margin-top: $form-feedback-margin-top;\\n    @include font-size($form-feedback-font-size);\\n    color: $color;\\n  }\\n\\n  .#{$state}-tooltip {\\n    position: absolute;\\n    top: 100%;\\n    left: 0;\\n    z-index: 5;\\n    display: none;\\n    max-width: 100%; // Contain to parent when possible\\n    padding: $form-feedback-tooltip-padding-y $form-feedback-tooltip-padding-x;\\n    margin-top: .1rem;\\n    @include font-size($form-feedback-tooltip-font-size);\\n    line-height: $form-feedback-tooltip-line-height;\\n    color: color-yiq($color);\\n    background-color: rgba($color, $form-feedback-tooltip-opacity);\\n    @include border-radius($form-feedback-tooltip-border-radius);\\n\\n    // See https://github.com/twbs/bootstrap/pull/31557\\n    // Align tooltip to form elements\\n    .form-row > .col > &,\\n    .form-row > [class*=\\"col-\\"] > & {\\n      left: $form-grid-gutter-width * .5;\\n    }\\n  }\\n\\n  @include form-validation-state-selector($state) {\\n    ~ .#{$state}-feedback,\\n    ~ .#{$state}-tooltip {\\n      display: block;\\n    }\\n  }\\n\\n  .form-control {\\n    @include form-validation-state-selector($state) {\\n      border-color: $color;\\n\\n      @if $enable-validation-icons {\\n        padding-right: $input-height-inner !important; // stylelint-disable-line declaration-no-important\\n        background-image: escape-svg($icon);\\n        background-repeat: no-repeat;\\n        background-position: right $input-height-inner-quarter center;\\n        background-size: $input-height-inner-half $input-height-inner-half;\\n      }\\n\\n      &:focus {\\n        border-color: $color;\\n        box-shadow: 0 0 0 $input-focus-width rgba($color, .25);\\n      }\\n    }\\n  }\\n\\n  // stylelint-disable-next-line selector-no-qualifying-type\\n  select.form-control {\\n    @include form-validation-state-selector($state) {\\n      @if $enable-validation-icons {\\n        padding-right: $input-padding-x * 4 !important; // stylelint-disable-line declaration-no-important\\n        background-position: right $input-padding-x * 2 center;\\n      }\\n    }\\n  }\\n\\n  // stylelint-disable-next-line selector-no-qualifying-type\\n  textarea.form-control {\\n    @include form-validation-state-selector($state) {\\n      @if $enable-validation-icons {\\n        padding-right: $input-height-inner;\\n        background-position: top $input-height-inner-quarter right $input-height-inner-quarter;\\n      }\\n    }\\n  }\\n\\n  .custom-select {\\n    @include form-validation-state-selector($state) {\\n      border-color: $color;\\n\\n      @if $enable-validation-icons {\\n        padding-right: $custom-select-feedback-icon-padding-right !important; // stylelint-disable-line declaration-no-important\\n        background: $custom-select-background, $custom-select-bg escape-svg($icon) $custom-select-feedback-icon-position / $custom-select-feedback-icon-size no-repeat;\\n      }\\n\\n      &:focus {\\n        border-color: $color;\\n        box-shadow: 0 0 0 $input-focus-width rgba($color, .25);\\n      }\\n    }\\n  }\\n\\n  .form-check-input {\\n    @include form-validation-state-selector($state) {\\n      ~ .form-check-label {\\n        color: $color;\\n      }\\n\\n      ~ .#{$state}-feedback,\\n      ~ .#{$state}-tooltip {\\n        display: block;\\n      }\\n    }\\n  }\\n\\n  .custom-control-input {\\n    @include form-validation-state-selector($state) {\\n      ~ .custom-control-label {\\n        color: $color;\\n\\n        &::before {\\n          border-color: $color;\\n        }\\n      }\\n\\n      &:checked {\\n        ~ .custom-control-label::before {\\n          border-color: lighten($color, 10%);\\n          @include gradient-bg(lighten($color, 10%));\\n        }\\n      }\\n\\n      &:focus {\\n        ~ .custom-control-label::before {\\n          box-shadow: 0 0 0 $input-focus-width rgba($color, .25);\\n        }\\n\\n        &:not(:checked) ~ .custom-control-label::before {\\n          border-color: $color;\\n        }\\n      }\\n    }\\n  }\\n\\n  // custom file\\n  .custom-file-input {\\n    @include form-validation-state-selector($state) {\\n      ~ .custom-file-label {\\n        border-color: $color;\\n      }\\n\\n      &:focus {\\n        ~ .custom-file-label {\\n          border-color: $color;\\n          box-shadow: 0 0 0 $input-focus-width rgba($color, .25);\\n        }\\n      }\\n    }\\n  }\\n}\\n","// Gradients\\n\\n@mixin gradient-bg($color) {\\n  @if $enable-gradients {\\n    background: $color linear-gradient(180deg, mix($body-bg, $color, 15%), $color) repeat-x;\\n  } @else {\\n    background-color: $color;\\n  }\\n}\\n\\n// Horizontal gradient, from left to right\\n//\\n// Creates two color stops, start and end, by specifying a color and position for each color stop.\\n@mixin gradient-x($start-color: $gray-700, $end-color: $gray-800, $start-percent: 0%, $end-percent: 100%) {\\n  background-image: linear-gradient(to right, $start-color $start-percent, $end-color $end-percent);\\n  background-repeat: repeat-x;\\n}\\n\\n// Vertical gradient, from top to bottom\\n//\\n// Creates two color stops, start and end, by specifying a color and position for each color stop.\\n@mixin gradient-y($start-color: $gray-700, $end-color: $gray-800, $start-percent: 0%, $end-percent: 100%) {\\n  background-image: linear-gradient(to bottom, $start-color $start-percent, $end-color $end-percent);\\n  background-repeat: repeat-x;\\n}\\n\\n@mixin gradient-directional($start-color: $gray-700, $end-color: $gray-800, $deg: 45deg) {\\n  background-image: linear-gradient($deg, $start-color, $end-color);\\n  background-repeat: repeat-x;\\n}\\n@mixin gradient-x-three-colors($start-color: $blue, $mid-color: $purple, $color-stop: 50%, $end-color: $red) {\\n  background-image: linear-gradient(to right, $start-color, $mid-color $color-stop, $end-color);\\n  background-repeat: no-repeat;\\n}\\n@mixin gradient-y-three-colors($start-color: $blue, $mid-color: $purple, $color-stop: 50%, $end-color: $red) {\\n  background-image: linear-gradient($start-color, $mid-color $color-stop, $end-color);\\n  background-repeat: no-repeat;\\n}\\n@mixin gradient-radial($inner-color: $gray-700, $outer-color: $gray-800) {\\n  background-image: radial-gradient(circle, $inner-color, $outer-color);\\n  background-repeat: no-repeat;\\n}\\n@mixin gradient-striped($color: rgba($white, .15), $angle: 45deg) {\\n  background-image: linear-gradient($angle, $color 25%, transparent 25%, transparent 50%, $color 50%, $color 75%, transparent 75%, transparent);\\n}\\n","// stylelint-disable selector-no-qualifying-type\\n\\n//\\n// Base styles\\n//\\n\\n.btn {\\n  display: inline-block;\\n  font-family: $btn-font-family;\\n  font-weight: $btn-font-weight;\\n  color: $body-color;\\n  text-align: center;\\n  text-decoration: if($link-decoration == none, null, none);\\n  white-space: $btn-white-space;\\n  vertical-align: middle;\\n  user-select: none;\\n  background-color: transparent;\\n  border: $btn-border-width solid transparent;\\n  @include button-size($btn-padding-y, $btn-padding-x, $btn-font-size, $btn-line-height, $btn-border-radius);\\n  @include transition($btn-transition);\\n\\n  @include hover() {\\n    color: $body-color;\\n    text-decoration: none;\\n  }\\n\\n  &:focus,\\n  &.focus {\\n    outline: 0;\\n    box-shadow: $btn-focus-box-shadow;\\n  }\\n\\n  // Disabled comes first so active can properly restyle\\n  &.disabled,\\n  &:disabled {\\n    opacity: $btn-disabled-opacity;\\n    @include box-shadow(none);\\n  }\\n\\n  &:not(:disabled):not(.disabled) {\\n    cursor: if($enable-pointer-cursor-for-buttons, pointer, null);\\n\\n    &:active,\\n    &.active {\\n      @include box-shadow($btn-active-box-shadow);\\n\\n      &:focus {\\n        @include box-shadow($btn-focus-box-shadow, $btn-active-box-shadow);\\n      }\\n    }\\n  }\\n}\\n\\n// Future-proof disabling of clicks on `<a>` elements\\na.btn.disabled,\\nfieldset:disabled a.btn {\\n  pointer-events: none;\\n}\\n\\n\\n//\\n// Alternate buttons\\n//\\n\\n@each $color, $value in $theme-colors {\\n  .btn-#{$color} {\\n    @include button-variant($value, $value);\\n  }\\n}\\n\\n@each $color, $value in $theme-colors {\\n  .btn-outline-#{$color} {\\n    @include button-outline-variant($value);\\n  }\\n}\\n\\n\\n//\\n// Link buttons\\n//\\n\\n// Make a button look and behave like a link\\n.btn-link {\\n  font-weight: $font-weight-normal;\\n  color: $link-color;\\n  text-decoration: $link-decoration;\\n\\n  @include hover() {\\n    color: $link-hover-color;\\n    text-decoration: $link-hover-decoration;\\n  }\\n\\n  &:focus,\\n  &.focus {\\n    text-decoration: $link-hover-decoration;\\n  }\\n\\n  &:disabled,\\n  &.disabled {\\n    color: $btn-link-disabled-color;\\n    pointer-events: none;\\n  }\\n\\n  // No need for an active state here\\n}\\n\\n\\n//\\n// Button Sizes\\n//\\n\\n.btn-lg {\\n  @include button-size($btn-padding-y-lg, $btn-padding-x-lg, $btn-font-size-lg, $btn-line-height-lg, $btn-border-radius-lg);\\n}\\n\\n.btn-sm {\\n  @include button-size($btn-padding-y-sm, $btn-padding-x-sm, $btn-font-size-sm, $btn-line-height-sm, $btn-border-radius-sm);\\n}\\n\\n\\n//\\n// Block button\\n//\\n\\n.btn-block {\\n  display: block;\\n  width: 100%;\\n\\n  // Vertically space out multiple block buttons\\n  + .btn-block {\\n    margin-top: $btn-block-spacing-y;\\n  }\\n}\\n\\n// Specificity overrides\\ninput[type=\\"submit\\"],\\ninput[type=\\"reset\\"],\\ninput[type=\\"button\\"] {\\n  &.btn-block {\\n    width: 100%;\\n  }\\n}\\n","// Button variants\\n//\\n// Easily pump out default styles, as well as :hover, :focus, :active,\\n// and disabled options for all buttons\\n\\n@mixin button-variant($background, $border, $hover-background: darken($background, 7.5%), $hover-border: darken($border, 10%), $active-background: darken($background, 10%), $active-border: darken($border, 12.5%)) {\\n  color: color-yiq($background);\\n  @include gradient-bg($background);\\n  border-color: $border;\\n  @include box-shadow($btn-box-shadow);\\n\\n  @include hover() {\\n    color: color-yiq($hover-background);\\n    @include gradient-bg($hover-background);\\n    border-color: $hover-border;\\n  }\\n\\n  &:focus,\\n  &.focus {\\n    color: color-yiq($hover-background);\\n    @include gradient-bg($hover-background);\\n    border-color: $hover-border;\\n    @if $enable-shadows {\\n      @include box-shadow($btn-box-shadow, 0 0 0 $btn-focus-width rgba(mix(color-yiq($background), $border, 15%), .5));\\n    } @else {\\n      // Avoid using mixin so we can pass custom focus shadow properly\\n      box-shadow: 0 0 0 $btn-focus-width rgba(mix(color-yiq($background), $border, 15%), .5);\\n    }\\n  }\\n\\n  // Disabled comes first so active can properly restyle\\n  &.disabled,\\n  &:disabled {\\n    color: color-yiq($background);\\n    background-color: $background;\\n    border-color: $border;\\n    // Remove CSS gradients if they\'re enabled\\n    @if $enable-gradients {\\n      background-image: none;\\n    }\\n  }\\n\\n  &:not(:disabled):not(.disabled):active,\\n  &:not(:disabled):not(.disabled).active,\\n  .show > &.dropdown-toggle {\\n    color: color-yiq($active-background);\\n    background-color: $active-background;\\n    @if $enable-gradients {\\n      background-image: none; // Remove the gradient for the pressed/active state\\n    }\\n    border-color: $active-border;\\n\\n    &:focus {\\n      @if $enable-shadows and $btn-active-box-shadow != none {\\n        @include box-shadow($btn-active-box-shadow, 0 0 0 $btn-focus-width rgba(mix(color-yiq($background), $border, 15%), .5));\\n      } @else {\\n        // Avoid using mixin so we can pass custom focus shadow properly\\n        box-shadow: 0 0 0 $btn-focus-width rgba(mix(color-yiq($background), $border, 15%), .5);\\n      }\\n    }\\n  }\\n}\\n\\n@mixin button-outline-variant($color, $color-hover: color-yiq($color), $active-background: $color, $active-border: $color) {\\n  color: $color;\\n  border-color: $color;\\n\\n  @include hover() {\\n    color: $color-hover;\\n    background-color: $active-background;\\n    border-color: $active-border;\\n  }\\n\\n  &:focus,\\n  &.focus {\\n    box-shadow: 0 0 0 $btn-focus-width rgba($color, .5);\\n  }\\n\\n  &.disabled,\\n  &:disabled {\\n    color: $color;\\n    background-color: transparent;\\n  }\\n\\n  &:not(:disabled):not(.disabled):active,\\n  &:not(:disabled):not(.disabled).active,\\n  .show > &.dropdown-toggle {\\n    color: color-yiq($active-background);\\n    background-color: $active-background;\\n    border-color: $active-border;\\n\\n    &:focus {\\n      @if $enable-shadows and $btn-active-box-shadow != none {\\n        @include box-shadow($btn-active-box-shadow, 0 0 0 $btn-focus-width rgba($color, .5));\\n      } @else {\\n        // Avoid using mixin so we can pass custom focus shadow properly\\n        box-shadow: 0 0 0 $btn-focus-width rgba($color, .5);\\n      }\\n    }\\n  }\\n}\\n\\n// Button sizes\\n@mixin button-size($padding-y, $padding-x, $font-size, $line-height, $border-radius) {\\n  padding: $padding-y $padding-x;\\n  @include font-size($font-size);\\n  line-height: $line-height;\\n  // Manually declare to provide an override to the browser default\\n  @include border-radius($border-radius, 0);\\n}\\n",".fade {\\n  @include transition($transition-fade);\\n\\n  &:not(.show) {\\n    opacity: 0;\\n  }\\n}\\n\\n.collapse {\\n  &:not(.show) {\\n    display: none;\\n  }\\n}\\n\\n.collapsing {\\n  position: relative;\\n  height: 0;\\n  overflow: hidden;\\n  @include transition($transition-collapse);\\n\\n  &.width {\\n    width: 0;\\n    height: auto;\\n    @include transition($transition-collapse-width);\\n  }\\n}\\n","// The dropdown wrapper (`<div>`)\\n.dropup,\\n.dropright,\\n.dropdown,\\n.dropleft {\\n  position: relative;\\n}\\n\\n.dropdown-toggle {\\n  white-space: nowrap;\\n\\n  // Generate the caret automatically\\n  @include caret();\\n}\\n\\n// The dropdown menu\\n.dropdown-menu {\\n  position: absolute;\\n  top: 100%;\\n  left: 0;\\n  z-index: $zindex-dropdown;\\n  display: none; // none by default, but block on \\"open\\" of the menu\\n  float: left;\\n  min-width: $dropdown-min-width;\\n  padding: $dropdown-padding-y $dropdown-padding-x;\\n  margin: $dropdown-spacer 0 0; // override default ul\\n  @include font-size($dropdown-font-size);\\n  color: $dropdown-color;\\n  text-align: left; // Ensures proper alignment if parent has it changed (e.g., modal footer)\\n  list-style: none;\\n  background-color: $dropdown-bg;\\n  background-clip: padding-box;\\n  border: $dropdown-border-width solid $dropdown-border-color;\\n  @include border-radius($dropdown-border-radius);\\n  @include box-shadow($dropdown-box-shadow);\\n}\\n\\n@each $breakpoint in map-keys($grid-breakpoints) {\\n  @include media-breakpoint-up($breakpoint) {\\n    $infix: breakpoint-infix($breakpoint, $grid-breakpoints);\\n\\n    .dropdown-menu#{$infix}-left {\\n      right: auto;\\n      left: 0;\\n    }\\n\\n    .dropdown-menu#{$infix}-right {\\n      right: 0;\\n      left: auto;\\n    }\\n  }\\n}\\n\\n// Allow for dropdowns to go bottom up (aka, dropup-menu)\\n// Just add .dropup after the standard .dropdown class and you\'re set.\\n.dropup {\\n  .dropdown-menu {\\n    top: auto;\\n    bottom: 100%;\\n    margin-top: 0;\\n    margin-bottom: $dropdown-spacer;\\n  }\\n\\n  .dropdown-toggle {\\n    @include caret(up);\\n  }\\n}\\n\\n.dropright {\\n  .dropdown-menu {\\n    top: 0;\\n    right: auto;\\n    left: 100%;\\n    margin-top: 0;\\n    margin-left: $dropdown-spacer;\\n  }\\n\\n  .dropdown-toggle {\\n    @include caret(right);\\n    &::after {\\n      vertical-align: 0;\\n    }\\n  }\\n}\\n\\n.dropleft {\\n  .dropdown-menu {\\n    top: 0;\\n    right: 100%;\\n    left: auto;\\n    margin-top: 0;\\n    margin-right: $dropdown-spacer;\\n  }\\n\\n  .dropdown-toggle {\\n    @include caret(left);\\n    &::before {\\n      vertical-align: 0;\\n    }\\n  }\\n}\\n\\n// When Popper is enabled, reset the basic dropdown position\\n// stylelint-disable-next-line no-duplicate-selectors\\n.dropdown-menu {\\n  &[x-placement^=\\"top\\"],\\n  &[x-placement^=\\"right\\"],\\n  &[x-placement^=\\"bottom\\"],\\n  &[x-placement^=\\"left\\"] {\\n    right: auto;\\n    bottom: auto;\\n  }\\n}\\n\\n// Dividers (basically an `<hr>`) within the dropdown\\n.dropdown-divider {\\n  @include nav-divider($dropdown-divider-bg, $dropdown-divider-margin-y, true);\\n}\\n\\n// Links, buttons, and more within the dropdown menu\\n//\\n// `<button>`-specific styles are denoted with `// For <button>s`\\n.dropdown-item {\\n  display: block;\\n  width: 100%; // For `<button>`s\\n  padding: $dropdown-item-padding-y $dropdown-item-padding-x;\\n  clear: both;\\n  font-weight: $font-weight-normal;\\n  color: $dropdown-link-color;\\n  text-align: inherit; // For `<button>`s\\n  text-decoration: if($link-decoration == none, null, none);\\n  white-space: nowrap; // prevent links from randomly breaking onto new lines\\n  background-color: transparent; // For `<button>`s\\n  border: 0; // For `<button>`s\\n\\n  // Prevent dropdown overflow if there\'s no padding\\n  // See https://github.com/twbs/bootstrap/pull/27703\\n  @if $dropdown-padding-y == 0 {\\n    &:first-child {\\n      @include border-top-radius($dropdown-inner-border-radius);\\n    }\\n\\n    &:last-child {\\n      @include border-bottom-radius($dropdown-inner-border-radius);\\n    }\\n  }\\n\\n  @include hover-focus() {\\n    color: $dropdown-link-hover-color;\\n    text-decoration: none;\\n    @include gradient-bg($dropdown-link-hover-bg);\\n  }\\n\\n  &.active,\\n  &:active {\\n    color: $dropdown-link-active-color;\\n    text-decoration: none;\\n    @include gradient-bg($dropdown-link-active-bg);\\n  }\\n\\n  &.disabled,\\n  &:disabled {\\n    color: $dropdown-link-disabled-color;\\n    pointer-events: none;\\n    background-color: transparent;\\n    // Remove CSS gradients if they\'re enabled\\n    @if $enable-gradients {\\n      background-image: none;\\n    }\\n  }\\n}\\n\\n.dropdown-menu.show {\\n  display: block;\\n}\\n\\n// Dropdown section headers\\n.dropdown-header {\\n  display: block;\\n  padding: $dropdown-header-padding;\\n  margin-bottom: 0; // for use with heading elements\\n  @include font-size($font-size-sm);\\n  color: $dropdown-header-color;\\n  white-space: nowrap; // as with > li > a\\n}\\n\\n// Dropdown text\\n.dropdown-item-text {\\n  display: block;\\n  padding: $dropdown-item-padding-y $dropdown-item-padding-x;\\n  color: $dropdown-link-color;\\n}\\n","@mixin caret-down() {\\n  border-top: $caret-width solid;\\n  border-right: $caret-width solid transparent;\\n  border-bottom: 0;\\n  border-left: $caret-width solid transparent;\\n}\\n\\n@mixin caret-up() {\\n  border-top: 0;\\n  border-right: $caret-width solid transparent;\\n  border-bottom: $caret-width solid;\\n  border-left: $caret-width solid transparent;\\n}\\n\\n@mixin caret-right() {\\n  border-top: $caret-width solid transparent;\\n  border-right: 0;\\n  border-bottom: $caret-width solid transparent;\\n  border-left: $caret-width solid;\\n}\\n\\n@mixin caret-left() {\\n  border-top: $caret-width solid transparent;\\n  border-right: $caret-width solid;\\n  border-bottom: $caret-width solid transparent;\\n}\\n\\n@mixin caret($direction: down) {\\n  @if $enable-caret {\\n    &::after {\\n      display: inline-block;\\n      margin-left: $caret-spacing;\\n      vertical-align: $caret-vertical-align;\\n      content: \\"\\";\\n      @if $direction == down {\\n        @include caret-down();\\n      } @else if $direction == up {\\n        @include caret-up();\\n      } @else if $direction == right {\\n        @include caret-right();\\n      }\\n    }\\n\\n    @if $direction == left {\\n      &::after {\\n        display: none;\\n      }\\n\\n      &::before {\\n        display: inline-block;\\n        margin-right: $caret-spacing;\\n        vertical-align: $caret-vertical-align;\\n        content: \\"\\";\\n        @include caret-left();\\n      }\\n    }\\n\\n    &:empty::after {\\n      margin-left: 0;\\n    }\\n  }\\n}\\n","// Horizontal dividers\\n//\\n// Dividers (basically an hr) within dropdowns and nav lists\\n\\n@mixin nav-divider($color: $nav-divider-color, $margin-y: $nav-divider-margin-y, $ignore-warning: false) {\\n  height: 0;\\n  margin: $margin-y 0;\\n  overflow: hidden;\\n  border-top: 1px solid $color;\\n  @include deprecate(\\"The `nav-divider()` mixin\\", \\"v4.4.0\\", \\"v5\\", $ignore-warning);\\n}\\n","// stylelint-disable selector-no-qualifying-type\\n\\n// Make the div behave like a button\\n.btn-group,\\n.btn-group-vertical {\\n  position: relative;\\n  display: inline-flex;\\n  vertical-align: middle; // match .btn alignment given font-size hack above\\n\\n  > .btn {\\n    position: relative;\\n    flex: 1 1 auto;\\n\\n    // Bring the hover, focused, and \\"active\\" buttons to the front to overlay\\n    // the borders properly\\n    @include hover() {\\n      z-index: 1;\\n    }\\n    &:focus,\\n    &:active,\\n    &.active {\\n      z-index: 1;\\n    }\\n  }\\n}\\n\\n// Optional: Group multiple button groups together for a toolbar\\n.btn-toolbar {\\n  display: flex;\\n  flex-wrap: wrap;\\n  justify-content: flex-start;\\n\\n  .input-group {\\n    width: auto;\\n  }\\n}\\n\\n.btn-group {\\n  // Prevent double borders when buttons are next to each other\\n  > .btn:not(:first-child),\\n  > .btn-group:not(:first-child) {\\n    margin-left: -$btn-border-width;\\n  }\\n\\n  // Reset rounded corners\\n  > .btn:not(:last-child):not(.dropdown-toggle),\\n  > .btn-group:not(:last-child) > .btn {\\n    @include border-right-radius(0);\\n  }\\n\\n  > .btn:not(:first-child),\\n  > .btn-group:not(:first-child) > .btn {\\n    @include border-left-radius(0);\\n  }\\n}\\n\\n// Sizing\\n//\\n// Remix the default button sizing classes into new ones for easier manipulation.\\n\\n.btn-group-sm > .btn { @extend .btn-sm; }\\n.btn-group-lg > .btn { @extend .btn-lg; }\\n\\n\\n//\\n// Split button dropdowns\\n//\\n\\n.dropdown-toggle-split {\\n  padding-right: $btn-padding-x * .75;\\n  padding-left: $btn-padding-x * .75;\\n\\n  &::after,\\n  .dropup &::after,\\n  .dropright &::after {\\n    margin-left: 0;\\n  }\\n\\n  .dropleft &::before {\\n    margin-right: 0;\\n  }\\n}\\n\\n.btn-sm + .dropdown-toggle-split {\\n  padding-right: $btn-padding-x-sm * .75;\\n  padding-left: $btn-padding-x-sm * .75;\\n}\\n\\n.btn-lg + .dropdown-toggle-split {\\n  padding-right: $btn-padding-x-lg * .75;\\n  padding-left: $btn-padding-x-lg * .75;\\n}\\n\\n\\n// The clickable button for toggling the menu\\n// Set the same inset shadow as the :active state\\n.btn-group.show .dropdown-toggle {\\n  @include box-shadow($btn-active-box-shadow);\\n\\n  // Show no shadow for `.btn-link` since it has no other button styles.\\n  &.btn-link {\\n    @include box-shadow(none);\\n  }\\n}\\n\\n\\n//\\n// Vertical button groups\\n//\\n\\n.btn-group-vertical {\\n  flex-direction: column;\\n  align-items: flex-start;\\n  justify-content: center;\\n\\n  > .btn,\\n  > .btn-group {\\n    width: 100%;\\n  }\\n\\n  > .btn:not(:first-child),\\n  > .btn-group:not(:first-child) {\\n    margin-top: -$btn-border-width;\\n  }\\n\\n  // Reset rounded corners\\n  > .btn:not(:last-child):not(.dropdown-toggle),\\n  > .btn-group:not(:last-child) > .btn {\\n    @include border-bottom-radius(0);\\n  }\\n\\n  > .btn:not(:first-child),\\n  > .btn-group:not(:first-child) > .btn {\\n    @include border-top-radius(0);\\n  }\\n}\\n\\n\\n// Checkbox and radio options\\n//\\n// In order to support the browser\'s form validation feedback, powered by the\\n// `required` attribute, we have to \\"hide\\" the inputs via `clip`. We cannot use\\n// `display: none;` or `visibility: hidden;` as that also hides the popover.\\n// Simply visually hiding the inputs via `opacity` would leave them clickable in\\n// certain cases which is prevented by using `clip` and `pointer-events`.\\n// This way, we ensure a DOM element is visible to position the popover from.\\n//\\n// See https://github.com/twbs/bootstrap/pull/12794 and\\n// https://github.com/twbs/bootstrap/pull/14559 for more information.\\n\\n.btn-group-toggle {\\n  > .btn,\\n  > .btn-group > .btn {\\n    margin-bottom: 0; // Override default `<label>` value\\n\\n    input[type=\\"radio\\"],\\n    input[type=\\"checkbox\\"] {\\n      position: absolute;\\n      clip: rect(0, 0, 0, 0);\\n      pointer-events: none;\\n    }\\n  }\\n}\\n","// stylelint-disable selector-no-qualifying-type\\n\\n//\\n// Base styles\\n//\\n\\n.input-group {\\n  position: relative;\\n  display: flex;\\n  flex-wrap: wrap; // For form validation feedback\\n  align-items: stretch;\\n  width: 100%;\\n\\n  > .form-control,\\n  > .form-control-plaintext,\\n  > .custom-select,\\n  > .custom-file {\\n    position: relative; // For focus state\'s z-index\\n    flex: 1 1 auto;\\n    width: 1%;\\n    min-width: 0; // https://stackoverflow.com/questions/36247140/why-dont-flex-items-shrink-past-content-size\\n    margin-bottom: 0;\\n\\n    + .form-control,\\n    + .custom-select,\\n    + .custom-file {\\n      margin-left: -$input-border-width;\\n    }\\n  }\\n\\n  // Bring the \\"active\\" form control to the top of surrounding elements\\n  > .form-control:focus,\\n  > .custom-select:focus,\\n  > .custom-file .custom-file-input:focus ~ .custom-file-label {\\n    z-index: 3;\\n  }\\n\\n  // Bring the custom file input above the label\\n  > .custom-file .custom-file-input:focus {\\n    z-index: 4;\\n  }\\n\\n  > .form-control,\\n  > .custom-select {\\n    &:not(:first-child) { @include border-left-radius(0); }\\n  }\\n\\n  // Custom file inputs have more complex markup, thus requiring different\\n  // border-radius overrides.\\n  > .custom-file {\\n    display: flex;\\n    align-items: center;\\n\\n    &:not(:last-child) .custom-file-label,\\n    &:not(:last-child) .custom-file-label::after { @include border-right-radius(0); }\\n   